-- ============================================================
-- Migration 052 -- Data kecamatan (districts) seluruh Indonesia
-- ============================================================
-- Sumber sama dengan migration 033: cahyadsn/wilayah, sesuai Kepmendagri
-- No 300.2.2-2138 Tahun 2025 (dump "last edit 2026-02-13", diunduh
-- 2026-11-09). 7.285 kecamatan, dicocokkan ke regencies lewat nama
-- provinsi + nama kota/kabupaten (regencies tidak menyimpan kode wilayah).
--
-- Kenapa sekarang (keputusan Andi, 9 Nov 2026): kecamatan ditampilkan di
-- Etalase publik (pelanggan tahu lokasi rental lebih persis) dan disiapkan
-- untuk REKAP PER WILAYAH dengan cakupan lebih kecil dari kota/kabupaten.
-- `code` (mis. "35.73.05") disimpan supaya rekap nanti bisa dikelompokkan
-- stabil walau nama kecamatan berubah.
--
-- Kecamatan TIDAK wajib: businesses.district_id / public_pages.district_id
-- nullable. FK komposit (district_id, regency_id) memastikan kecamatan yang
-- dipilih selalu milik kota/kabupaten yang sama -- baris dengan
-- district_id null lolos otomatis (MATCH SIMPLE).
--
-- Idempotent: aman dijalankan ulang.
-- ============================================================

create table if not exists districts (
  id          uuid primary key default gen_random_uuid(),
  regency_id  uuid not null references regencies(id),
  code        text not null unique,      -- kode Kemendagri, "35.73.05"
  name        text not null,             -- "Lowokwaru"
  unique (regency_id, name),
  unique (id, regency_id)                -- target FK komposit di bawah
);
create index if not exists districts_regency_idx on districts (regency_id);

alter table districts enable row level security;
drop policy if exists "public_read_districts" on districts;
create policy "public_read_districts" on districts for select using (true);

insert into districts (regency_id, code, name)
select r.id, v.code, v.name
from (values
