join provinces p on p.name = v.province_name
join regencies r on r.province_id = p.id and r.name = v.regency_name
on conflict (code) do nothing;

-- Pengaman: kalau ada baris sumber yang gagal dicocokkan ke regencies,
-- migrasi gagal di sini (bukan diam-diam kehilangan kecamatan).
do $$
declare n int;
begin
  select count(*) into n from districts;
  if n < 7285 then
    raise exception 'districts cuma % baris, harusnya 7285 -- cek nama provinsi/kota', n;
  end if;
end $$;

-- ------------------------------------------------------------
-- Kolom kecamatan di Info Usaha & Etalase
-- ------------------------------------------------------------
alter table businesses   add column if not exists district_id uuid;
alter table public_pages add column if not exists district_id uuid;

alter table businesses drop constraint if exists businesses_district_fk;
alter table businesses add constraint businesses_district_fk
  foreign key (district_id, regency_id) references districts (id, regency_id);

alter table public_pages drop constraint if exists public_pages_district_fk;
alter table public_pages add constraint public_pages_district_fk
  foreign key (district_id, regency_id) references districts (id, regency_id);

-- ------------------------------------------------------------
-- get_public_page -- tambah district_name. Basis: versi terakhir di
-- migration 047 (044/048-051 tidak mengubahnya lagi), cuma 1 kolom + 1 join.
-- ------------------------------------------------------------
create or replace function get_public_page(p_slug text)
returns json
language plpgsql
security definer
set search_path = public
stable
as $$
declare
  result json;
begin
  select json_build_object(
    'business_name', b.name,
    'logo_url', b.logo_url,
    'description', pp.description,
    'address', pp.address,
    'regency_name', r.name,
    'district_name', d.name,
    'operating_hours', pp.operating_hours,
    'public_phone', pp.public_phone,
    'writable', business_is_writable(pp.business_id),
    'terms_content', rtv.content,
    -- Tidak sensitif (cuma uuid internal) — dibutuhkan klien untuk
    -- dikirim balik persis sebagai p_terms_version_id saat submit, biar
    -- server bisa menolak kalau sudah tidak current lagi (lihat bagian 4).
    'terms_version_id', pp.current_terms_version_id,
    'items', (
      select coalesce(json_agg(
        json_build_object(
          'id', i.id,
          'name', i.name,
          'category', i.category,
          'price_per_day', i.price_per_day,
          'day2_rate', i.day2_rate,
          'day3_rate', i.day3_rate,
          'day4_rate', i.day4_rate,
          'day5_rate', i.day5_rate,
          'extra_day_rate', i.extra_day_rate,
          'image_url', i.image_url,
          'variant', i.variant,
          'size', i.size,
          'color', i.color
        )
        order by i.name
      ), '[]'::json)
      from items i
      where i.business_id = pp.business_id
        and i.deactivated_at is null
    )
  )
  into result
  from public_pages pp
  join businesses b on b.id = pp.business_id
  left join regencies r on r.id = pp.regency_id
  left join districts d on d.id = pp.district_id
  left join rental_terms_versions rtv on rtv.id = pp.current_terms_version_id
  where pp.slug = p_slug
    and pp.published = true;

  return result;
end;
$$;

grant execute on function get_public_page(text) to anon, authenticated;
